  const fmtT = (m) => { m = Math.round(m); const hh = Math.floor(m / 60) % 24, mm = m % 60; return `${String(hh).padStart(2, "0")}:${String(mm).padStart(2, "0")}`; };
  const fmtDur = (m) => { m = Math.round(m); if (m < 60) return `${m} ${t("u.min")}`; const hh = Math.floor(m / 60), mm = m % 60; return mm ? `${hh} ${t("u.h")} ${mm}` : `${hh} ${t("u.h")}`; };
  const fmtKm = (m) => (m >= 1000 ? `${(m / 1000).toLocaleString(LOCALE(), { minimumFractionDigits: 1, maximumFractionDigits: 1 })} ${t("u.km")}` : `${Math.round(m / 10) * 10} ${t("u.m")}`);
